class ItineraryActivity { const ItineraryActivity({required this.id,required this.title,required this.durationMinutes,this.priority=0,this.mustDo=false}); final String id,title; final int durationMinutes,priority; final bool mustDo; }
class ItineraryPlan { const ItineraryPlan(this.scheduled,this.unscheduled,this.usedMinutes); final List<ItineraryActivity> scheduled,unscheduled; final int usedMinutes; }
class ItineraryPlanner { const ItineraryPlanner(); ItineraryPlan plan(Iterable<ItineraryActivity> items,{required int availableMinutes}){if(availableMinutes<0)throw ArgumentError.value(availableMinutes);final seen=<String>{};final valid=items.where((a)=>a.id.trim().isNotEmpty&&seen.add(a.id)&&a.durationMinutes>0).toList()..sort((a,b){final m=b.mustDo.compareTo(a.mustDo);if(m!=0)return m;final p=b.priority.compareTo(a.priority);return p!=0?p:a.id.compareTo(b.id);});final yes=<ItineraryActivity>[],no=<ItineraryActivity>[];var used=0;for(final a in valid){if(used+a.durationMinutes<=availableMinutes){yes.add(a);used+=a.durationMinutes;}else{no.add(a);}}return ItineraryPlan(List.unmodifiable(yes),List.unmodifiable(no),used);}}
